sp_widget.client_script:
api.controller = function() {

    var c = this;


    // =====================================================
    // FIND CURRENT STATUS OPTION
    // =====================================================

    function setCurrentStatus() {

        if (
            !c.data.company ||
            !c.data.status_options ||
            !c.data.status_options.length
        ) {

            return;

        }


        var currentValue =
            c.data.company.status_value;


        var currentLabel =
            c.data.company.status;


        // -------------------------------------------------
        // First: match database value
        // -------------------------------------------------

        for (
            var i = 0;
            i < c.data.status_options.length;
            i++
        ) {

            if (
                String(
                    c.data.status_options[i].value
                ) ===
                String(
                    currentValue
                )
            ) {

                c.editStatus =
                    c.data.status_options[i].value;

                return;

            }

        }


        // -------------------------------------------------
        // Second: match display label
        // -------------------------------------------------

        for (
            var j = 0;
            j < c.data.status_options.length;
            j++
        ) {

            if (
                String(
                    c.data.status_options[j].label
                ).toLowerCase() ===
                String(
                    currentLabel
                ).toLowerCase()
            ) {

                c.editStatus =
                    c.data.status_options[j].value;

                return;

            }

        }


        // -------------------------------------------------
        // Final fallback
        // -------------------------------------------------

        c.editStatus =
            c.data.status_options[0].value;

    }


    // =====================================================
    // INITIAL LOAD
    // =====================================================

    setCurrentStatus();


    // =====================================================
    // UPDATE COMPANY STATUS
    // =====================================================

    c.updateStatus = function() {

        if (
            !c.editStatus
        ) {

            return;

        }


        c.updatingStatus =
            true;


        c.server.get({

            action:
                'update_status',

            status:
                c.editStatus

        }).then(function(response) {

            c.updatingStatus =
                false;


            // -------------------------------------------------
            // Replace data with fresh server data
            // -------------------------------------------------

            c.data =
                response.data;


            // -------------------------------------------------
            // Re-select updated status
            // -------------------------------------------------

            setCurrentStatus();

        }).catch(function() {

            c.updatingStatus =
                false;

        });

    };

};

sp_widget.css:
.company-profile-page {
    max-width: 1080px;
    margin: 0 auto;
    padding: 28px;
    color: #102a56;
}


/* HEADER */

.profile-header {
    background: linear-gradient(
        135deg,
        #f4f3ff,
        #eef1ff
    );

    border: 1px solid #dfe3ff;
    border-radius: 18px;

    padding: 30px;

    display: flex;
    justify-content: space-between;
    align-items: center;

    margin-bottom: 22px;
}


.eyebrow {
    font-size: 11px;
    letter-spacing: 2px;
    font-weight: 700;
    color: #5267e8;
}


.profile-header h1 {
    margin: 8px 0 5px;
    font-size: 28px;
    color: #082b62;
}


.profile-header p {
    margin: 0;
    color: #66789b;
}


/* BUTTON */

.btn {
    display: inline-block;
    padding: 11px 18px;
    border-radius: 9px;
    text-decoration: none;
    font-size: 13px;
    font-weight: 600;
}


.btn-secondary {
    border: 1px solid #cbd5ef;
    background: white;
    color: #3156e8;
}


/* PROFILE CARD */

.profile-card {
    background: white;
    border: 1px solid #dce3f0;
    border-radius: 18px;

    box-shadow:
        0 8px 25px rgba(40, 65, 110, 0.06);

    overflow: hidden;
}


/* COMPANY TOP */

.company-top {
    padding: 28px;

    display: flex;
    align-items: center;
    gap: 18px;

    border-bottom: 1px solid #edf0f6;
}


.company-logo {
    width: 62px;
    height: 62px;

    border-radius: 14px;

    background: #5267e8;
    color: white;

    display: flex;
    align-items: center;
    justify-content: center;

    font-size: 25px;
    font-weight: 700;
}


.company-top h2 {
    margin: 0 0 5px;
    color: #092c62;
    font-size: 23px;
}


.company-id {
    font-size: 12px;
    color: #71809c;
}


.company-status {
    margin-left: auto;
}


.status-badge {
    display: inline-block;

    padding: 6px 13px;

    border-radius: 20px;

    background: #e8f8ef;
    color: #16834a;

    font-size: 12px;
    font-weight: 600;
}


/* SECTION */

.section {
    padding: 28px;
    border-bottom: 1px solid #edf0f6;
}


.section:last-child {
    border-bottom: none;
}


.section-title {
    font-size: 16px;
    font-weight: 700;

    color: #173b70;

    margin-bottom: 20px;
}


/* DETAILS */

.details-grid {
    display: grid;

    grid-template-columns:
        repeat(2, 1fr);

    gap: 22px 40px;
}


.detail-item {
    display: flex;
    flex-direction: column;
    gap: 6px;
}


.detail-label {
    font-size: 11px;

    text-transform: uppercase;

    letter-spacing: 0.7px;

    color: #7a89a5;
}


.detail-value {
    font-size: 14px;

    color: #193964;

    font-weight: 600;
}


/* RECRUITER */

.recruiter-card {
    display: flex;
    align-items: center;

    gap: 18px;

    background: #f8f9ff;

    border: 1px solid #e4e8f8;

    border-radius: 12px;

    padding: 20px;
}


.recruiter-avatar {
    width: 52px;
    height: 52px;

    border-radius: 50%;

    background: #e9edff;

    color: #5267e8;

    display: flex;
    align-items: center;
    justify-content: center;

    font-size: 20px;
    font-weight: 700;
}


.recruiter-details {
    display: grid;

    grid-template-columns:
        repeat(2, 1fr);

    gap: 30px;

    flex: 1;
}


/* ERROR */

.error-message {
    padding: 18px;

    background: #fff2f2;

    border: 1px solid #ffd2d2;

    border-radius: 10px;

    color: #c62828;

    margin-bottom: 20px;
}


/* RESPONSIVE */

@media (max-width: 700px) {

    .profile-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 20px;
    }

    .details-grid {
        grid-template-columns: 1fr;
    }

    .recruiter-details {
        grid-template-columns: 1fr;
    }

}


/* =========================================
   STATUS EDIT
========================================= */

.status-edit-row {

    display: flex;

    align-items: center;

    gap: 10px;

    margin-top: 2px;

}


.status-select {

    height: 38px;

    min-width: 125px;

    padding:
        0 34px 0 12px;

    border:
        1px solid #cbd5ef;

    border-radius: 8px;

    background: #ffffff;

    color: #193964;

    font-size: 13px;

    font-weight: 600;

    cursor: pointer;

    outline: none;

}


.status-select:focus {

    border-color: #5267e8;

    box-shadow:
        0 0 0 3px
        rgba(82,103,232,0.10);

}


.update-status-btn {

    height: 38px;

    padding:
        0 16px;

    border-radius: 8px;

    border: none;

    font-size: 12px;

}


.update-status-btn:disabled {

    opacity: 0.6;

    cursor: not-allowed;

}


/* =========================================
   STATUS BADGES
========================================= */

.status-active {

    background: #e8f8ef;

    color: #16834a;

}


.status-inactive {

    background: #fff1f1;

    color: #c62828;

}


/* =========================================
   SUCCESS MESSAGE
========================================= */

.success-message {

    padding:
        14px 18px;

    background: #eaf8ef;

    border:
        1px solid #c9ecd8;

    border-radius: 10px;

    color: #16834a;

    margin-bottom: 20px;

    font-size: 13px;

    font-weight: 600;

}

sp_widget.script:
(function() {

    // =====================================================
    // CAMPUS360 RECRUITER - COMPANY PROFILE
    // =====================================================
    //
    // Current Recruiter:
    // Ananya Mehta
    // Recruiter ID:
    // RCR001
    //
    // Current Company:
    // TechNova Solutions
    // Company ID:
    // CMP001
    //
    // This widget:
    // 1. Loads company information
    // 2. Loads company status choices
    // 3. Allows recruiter to update company status
    // 4. Saves the change to Company Master
    // =====================================================


    // =====================================================
    // RECRUITER CONTEXT
    // =====================================================

    data.recruiter_name =
        'Ananya Mehta';

    data.recruiter_id =
        'RCR001';


    // =====================================================
    // COMPANY CONTEXT
    // =====================================================

    // TechNova Solutions - CMP001
    var companySysId =
        'e9268662acd303107f44b432e349694b';


    // =====================================================
    // CLEAR MESSAGES
    // =====================================================

    data.error = '';
    data.success = '';


    // =====================================================
    // UPDATE COMPANY STATUS
    // =====================================================

    if (
        input &&
        input.action == 'update_status'
    ) {

        var newStatus =
            input.status;


        // -------------------------------------------------
        // Validate status
        // -------------------------------------------------

        if (!newStatus) {

            data.error =
                'Please select a valid company status.';

        } else {

            // -------------------------------------------------
            // Get company record
            // -------------------------------------------------

            var updateCompany =
                new GlideRecord(
                    'x_snc_campus360_company_master'
                );


            if (
                updateCompany.get(companySysId)
            ) {

                // -------------------------------------------------
                // Verify that selected status exists
                // in the Company Master choice list
                // -------------------------------------------------

                var validStatus = false;


                var statusChoice =
                    new GlideRecord('sys_choice');


                statusChoice.addQuery(
                    'name',
                    'x_snc_campus360_company_master'
                );


                statusChoice.addQuery(
                    'element',
                    'status'
                );


                statusChoice.addQuery(
                    'value',
                    newStatus
                );


                statusChoice.addQuery(
                    'inactive',
                    false
                );


                statusChoice.query();


                if (
                    statusChoice.next()
                ) {

                    validStatus = true;

                }


                // -------------------------------------------------
                // Update status
                // -------------------------------------------------

                if (validStatus) {

                    updateCompany.setValue(
                        'status',
                        newStatus
                    );


                    updateCompany.update();


                    data.success =
                        'Company status updated successfully.';

                } else {

                    data.error =
                        'Invalid company status selected.';

                }

            } else {

                data.error =
                    'Company record could not be found.';

            }

        }

    }


    // =====================================================
    // GET COMPANY
    // =====================================================

    var companyGR =
        new GlideRecord(
            'x_snc_campus360_company_master'
        );


    if (
        !companyGR.get(companySysId)
    ) {

        data.error =
            'Company record could not be found.';

        return;

    }


    // =====================================================
    // CURRENT STATUS
    // =====================================================

    /*
     * Actual value stored in the database.
     *
     * Example:
     * active
     * inactive
     * or another ServiceNow choice value.
     */

    var currentStatus =
        companyGR.getValue('status');


    /*
     * Display label.
     *
     * Example:
     * Active
     * Inactive
     */

    var currentStatusDisplay =
        companyGR.getDisplayValue('status');


    // =====================================================
    // COMPANY INFORMATION
    // =====================================================

    data.company = {

        // -------------------------------------------------
        // SYS ID
        // -------------------------------------------------

        sys_id:
            companyGR.getUniqueValue(),


        // -------------------------------------------------
        // COMPANY NAME
        // -------------------------------------------------

        company_name:
            companyGR.getValue(
                'company_name'
            ),


        // -------------------------------------------------
        // COMPANY ID
        // -------------------------------------------------

        company_id:
            companyGR.getValue(
                'company_id'
            ),


        // -------------------------------------------------
        // COMPANY TYPE
        // -------------------------------------------------

        company_type:
            companyGR.getDisplayValue(
                'company_type'
            ),


        // -------------------------------------------------
        // INDUSTRY
        // -------------------------------------------------

        industry:
            companyGR.getDisplayValue(
                'industry'
            ),


        // -------------------------------------------------
        // CONTACT NUMBER
        // -------------------------------------------------

        contact_number:
            companyGR.getValue(
                'contact_number'
            ),


        // -------------------------------------------------
        // RECRUITER NAME
        // -------------------------------------------------

        recruiter_name:
            companyGR.getValue(
                'recruiter_name'
            ),


        // -------------------------------------------------
        // RECRUITER EMAIL
        // -------------------------------------------------

        recruiter_email:
            companyGR.getValue(
                'recruiter_email'
            ),


        // -------------------------------------------------
        // STATUS DISPLAY VALUE
        // -------------------------------------------------

        status:
            currentStatusDisplay,


        // -------------------------------------------------
        // STATUS DATABASE VALUE
        // -------------------------------------------------

        status_value:
            currentStatus

    };


    // =====================================================
    // STATUS OPTIONS
    // =====================================================

    data.status_options = [];


    // =====================================================
    // READ STATUS CHOICES FROM SERVICENOW
    // =====================================================

    var choiceGR =
        new GlideRecord('sys_choice');


    choiceGR.addQuery(
        'name',
        'x_snc_campus360_company_master'
    );


    choiceGR.addQuery(
        'element',
        'status'
    );


    choiceGR.addQuery(
        'inactive',
        false
    );


    choiceGR.orderBy(
        'sequence'
    );


    choiceGR.query();


    while (
        choiceGR.next()
    ) {

        data.status_options.push({

            value:
                choiceGR.getValue(
                    'value'
                ),

            label:
                choiceGR.getValue(
                    'label'
                )

        });

    }


    // =====================================================
    // FALLBACK STATUS OPTIONS
    // =====================================================

    /*
     * If ServiceNow does not return any
     * choices from sys_choice, create
     * fallback choices.
     */

    if (
        data.status_options.length == 0
    ) {

        // -------------------------------------------------
        // Current status
        // -------------------------------------------------

        if (currentStatus) {

            data.status_options.push({

                value:
                    currentStatus,

                label:
                    currentStatusDisplay

            });

        }


        // -------------------------------------------------
        // Add Active if current status isn't Active
        // -------------------------------------------------

        if (
            currentStatus != 'active'
        ) {

            data.status_options.push({

                value:
                    'active',

                label:
                    'Active'

            });

        }


        // -------------------------------------------------
        // Add Inactive if current status isn't Inactive
        // -------------------------------------------------

        if (
            currentStatus != 'inactive'
        ) {

            data.status_options.push({

                value:
                    'inactive',

                label:
                    'Inactive'

            });

        }

    }


    // =====================================================
    // ENSURE CURRENT STATUS EXISTS IN DROPDOWN
    // =====================================================

    /*
     * Sometimes the Company Master record can contain
     * a value which is not currently available in
     * sys_choice.
     *
     * We still want the current value to be visible.
     */

    var currentStatusExists =
        false;


    for (
        var i = 0;
        i < data.status_options.length;
        i++
    ) {

        if (
            String(
                data.status_options[i].value
            ) ===
            String(
                currentStatus
            )
        ) {

            currentStatusExists =
                true;

            break;

        }

    }


    // -----------------------------------------------------
    // Add current status if missing
    // -----------------------------------------------------

    if (
        currentStatus &&
        !currentStatusExists
    ) {

        data.status_options.unshift({

            value:
                currentStatus,

            label:
                currentStatusDisplay

        });

    }


    // =====================================================
    // FINAL DEBUG INFORMATION
    // =====================================================

    /*
     * Keep these while testing.
     * You can remove them later.
     */

    data.debug_status_value =
        currentStatus;


    data.debug_status_display =
        currentStatusDisplay;


})();
